def count_caesar_cipher_pairs(words):
    counts={};answer=0
    for word in words:
        key=tuple((ord(char)-ord(word[0]))%26 for char in word)
        answer+=counts.get(key,0);counts[key]=counts.get(key,0)+1
    return answer

